tabs=[t[0] for t in con.execute("select name from sqlite_master where type='table' and name not like 'sqlite_%' order by name")]
counts={t:con.execute(f'select count(*) from "{t}"').fetchone()[0] for t in tabs}
edges=[]; indeg={t:0 for t in tabs}; outdeg={t:0 for t in tabs}
for t in tabs:
    for r in con.execute(f'PRAGMA foreign_key_list("{t}")'):
        tgt=r[2]
        edges.append((t,r[3],tgt,r[4]))
        outdeg[t]+=1
        if tgt in indeg: indeg[tgt]+=1
print(f"tables: {len(tabs)}   declared FK edges: {len(edges)}\n")
iso=[t for t in tabs if indeg[t]==0 and outdeg[t]==0]
print(f"ISLANDS — no FK in or out ({len(iso)}):")
for t in iso: print(f"   {t:34s}{counts[t]:>7}")
print()
