import sqlite3, json, re
from pathlib import Path
con = sqlite3.connect('file:data/guidebook.db?mode=ro', uri=True)
# Direction DB -> artefact: for each evidence source, find logged payload
rows = con.execute("SELECT ref_id, doi, created_by_session FROM evidence_sources").fetchall()
for ref, doi, sess in rows:
    man = Path('retrieval-log')/sess/'manifest.jsonl'
    hits_doi, hits_ref = [], []
    if man.exists():
        for line in man.read_text().splitlines():
            r = json.loads(line)
            if doi and doi.lower() in r['url'].lower(): hits_doi.append(r['artefact'])
            if ref in r.get('purpose',''): hits_ref.append(r['artefact'])
    # also check other sessions' manifests for ref mention
    other = []
    for m in Path('retrieval-log').glob('*/manifest.jsonl'):
        if m == man: continue
        for line in m.read_text().splitlines():
            r = json.loads(line)
            if ref in r.get('purpose',''): other.append((m.parent.name, r['artefact']))
    print(ref, doi, "| session-manifest doi-hits:", hits_doi, "ref-in-purpose:", hits_ref, "| other-session ref hits:", len(other))
# Direction artefact -> DB: parse REF ids from purposes
print()
for m in Path('retrieval-log').glob('*/manifest.jsonl'):
    for line in m.read_text().splitlines():
        r = json.loads(line)
        refs = re.findall(r'REF-\d+', r.get('purpose',''))
        ok = [con.execute("SELECT 1 FROM evidence_sources WHERE ref_id=?", (x,)).fetchone() is not None for x in refs]
        print(m.parent.name, r['artefact'], refs, "resolves:", ok)
